/* provenance                                                                  */
/* -------------------------------------------------------------------------- */

const LICENSE_NOTE =
  'Original work, generated by scripts/make-music.ts in this repository and ' +
  'dedicated to the public domain under CC0 1.0. No performer, no sample ' +
  'library and no third-party recording is involved: every sample is computed ' +
  'from the chord progression and tempo written in that script, so the audio ' +
  'can be reproduced exactly by re-running it. There is nothing here for ' +
  'anyone to claim a licence fee on.';

function licenseText(piece: Piece, durationSec: number): string {
  return [
    `${piece.title} — licence and provenance`,
    '',
    'Licence: CC0 1.0 Universal (public domain dedication).',
    'https://creativecommons.org/publicdomain/zero/1.0/',
    '',
    'Provenance',
    '----------',
    'This recording was not obtained from anywhere. It was synthesised by',
    'scripts/make-music.ts in this repository: a small additive synthesiser',
    'renders the chord progression and melody written in that file, at the',
    'tempo written in that file, through a reverb written in that file, and',
    'ffmpeg encodes the result to AAC.',
    '',
    `  key       ${piece.key}`,
    `  tempo     ${piece.bpm} BPM`,
    `  length    ${durationSec.toFixed(1)} seconds`,
    `  seed      ${piece.seed} (deterministic — re-running reproduces this file)`,
    '',
    'Because the work is entirely original and machine-generated from that',
    'source, it carries no third-party rights: no composition licence, no',
    'master recording licence, no performing rights, no attribution required.',
    'A family may include it in a video and share that video anywhere.',
    '',
    'The CC0 dedication is made by the authors of this repository.',
  ].join('\n');
}

/* -------------------------------------------------------------------------- */
/* the script                                                                  */
/* -------------------------------------------------------------------------- */

async function probeDuration(file: string): Promise<number> {
  const result = await runFfprobe([
    '-v',
    'error',
    '-show_entries',
    'format=duration',
    '-of',
    'default=nw=1:nk=1',
    file,
  ]);
  return Number.parseFloat(result.stdout.trim());
}

export async function makeTrack(piece: Piece): Promise<MusicTrackMeta> {
  const dir = path.join(MUSIC_LIBRARY_DIR, piece.slug);
  await mkdir(dir, { recursive: true });

  const wavFile = path.join(dir, 'audio.wav');
  const audioFile = path.join(dir, 'audio.m4a');

  const { wav } = renderPiece(piece);
  await writeFile(wavFile, wav);
  await runFfmpeg(
    [
      '-hide_banner',
      '-nostdin',
      '-y',
      '-i',
      wavFile,
      '-c:a',
      'aac',
      '-b:a',
      BITRATE,
      '-ar',
      '44100',
      '-ac',
      '2',
      '-movflags',
      '+faststart',
      audioFile,
    ],
    { timeoutMs: 300_000 },
  );
  await rm(wavFile, { force: true });

  // The encoded length, not the synthesised one: the beat grid has to describe
  // the file a family will actually hear.
  const durationSec = Math.round((await probeDuration(audioFile)) * 1000) / 1000;

  const meta: MusicTrackMeta = {
    slug: piece.slug,
    title: piece.title,
    artist: 'Celebration of Life toolkit (generated)',
    durationSec,
    bpm: piece.bpm,
    licenseKind: 'public-domain',
    licenseNote: LICENSE_NOTE,
    acquiredAt: new Date().toISOString().slice(0, 10),
    verifiedBy: 'scripts/make-music.ts',
    moodTags: piece.moodTags,
    traditionTags: [],
    description: piece.description,
    beatGrid: beatGridFromBpm(piece.bpm, durationSec),
    audioFile: 'audio.m4a',
    mime: 'audio/mp4',
  };

  await writeFile(path.join(dir, 'meta.json'), `${JSON.stringify(meta, null, 2)}\n`);
  await writeFile(path.join(dir, 'LICENSE.txt'), `${licenseText(piece, durationSec)}\n`);
  return meta;
}

export async function makeMusicLibrary(): Promise<MusicTrackMeta[]> {
  const out: MusicTrackMeta[] = [];
  for (const piece of PIECES) {
    const startedAt = Date.now();
    const meta = await makeTrack(piece);
    const file = path.join(MUSIC_LIBRARY_DIR, piece.slug, 'audio.m4a');
    const size = (await stat(file)).size;
    console.log(
      `${meta.slug.padEnd(18)} ${meta.durationSec.toFixed(1)}s  ${meta.bpm} BPM  ` +
        `${(size / 1024 / 1024).toFixed(2)} MB  ${((Date.now() - startedAt) / 1000).toFixed(1)}s`,
    );
    if (size > 3 * 1024 * 1024) {
      console.warn(`  ! ${meta.slug} is over 3 MB — too big to keep in the repository.`);
    }
    out.push(meta);
  }
  return out;
}

const invokedDirectly =
  process.argv[1] && path.resolve(process.argv[1]) === path.resolve(here, 'make-music.ts');
if (invokedDirectly) {
  makeMusicLibrary()
    .then((tracks) => {
      console.log(`\n${tracks.length} tracks written to content/music-library.`);
    })
    .catch((error: unknown) => {
      console.error(error);
      process.exitCode = 1;
    });
}
